 10	import androidx.preference.Preference;
 11	import androidx.preference.PreferenceFragmentCompat;
 12	
 13	import com.termux.R;
 14	import com.termux.shared.activities.ReportActivity;
 15	import com.termux.shared.file.FileUtils;
 16	import com.termux.shared.models.ReportInfo;
 17	import com.termux.app.models.UserAction;
 18	import com.termux.shared.interact.ShareUtils;
 19	import com.termux.shared.android.PackageUtils;
 20	import com.termux.shared.android.AndroidUtils;
 21	import com.termux.shared.termux.TermuxConstants;
 22	import com.termux.shared.termux.TermuxUtils;
 23	import com.termux.shared.activity.media.AppCompatActivityUtils;
 24	import com.termux.shared.theme.NightMode;
 25	
 26	public class SettingsActivity extends AppCompatActivity {
 27	
 28	    @Override
 29	    protected void onCreate(Bundle savedInstanceState) {
 30	        super.onCreate(savedInstanceState);
 31	
 32	        AppCompatActivityUtils.setNightMode(this, NightMode.getAppNightMode().getName(), true);
 33	
 34	        setContentView(R.layout.activity_settings);
 35	        if (savedInstanceState == null) {
 36	            getSupportFragmentManager()
 37	                .beginTransaction()
 38	                .replace(R.id.settings, new RootPreferencesFragment())
 39	                .commit();
 40	        }
 41	
 42	        AppCompatActivityUtils.setToolbar(this, com.termux.shared.R.id.toolbar);
 43	        AppCompatActivityUtils.setShowBackButtonInActionBar(this, true);
 44	    }
 45	
 46	    @Override
 47	    public boolean onSupportNavigateUp() {
 48	        onBackPressed();
 49	        return true;
 50	    }
 51	
 52	    public static class RootPreferencesFragment extends PreferenceFragmentCompat {
 53	        @Override
 54	        public void onCreatePreferences(Bundle savedInstanceState, String rootKey) {
 55	            Context context = getContext();
 56	            if (context == null) return;
 57	
 58	            setPreferencesFromResource(R.xml.root_preferences, rootKey);
 59	
 60	            configurePluginPreference(context, "termux_api", TermuxConstants.TERMUX_API_PACKAGE_NAME);
 61	            configurePluginPreference(context, "termux_float", TermuxConstants.TERMUX_FLOAT_PACKAGE_NAME);
 62	            configurePluginPreference(context, "termux_tasker", TermuxConstants.TERMUX_TASKER_PACKAGE_NAME);
 63	            configurePluginPreference(context, "termux_widget", TermuxConstants.TERMUX_WIDGET_PACKAGE_NAME);
 64	            configureAboutPreference(context);
 65	            configureDonatePreference(context);
 66	        }
 67	
 68	        private void configurePluginPreference(@NonNull Context context, @NonNull String preferenceKey, @NonNull String packageName) {
 69	            Preference pluginPreference = findPreference(preferenceKey);
 70	            if (pluginPreference != null) {
 71	                pluginPreference.setVisible(PackageUtils.getContextForPackage(context, packageName) != null);
 72	            }
 73	        }
 74	
 75	        private void configureAboutPreference(@NonNull Context context) {
 76	            Preference aboutPreference = findPreference("about");
 77	            if (aboutPreference != null) {
 78	                aboutPreference.setOnPreferenceClickListener(preference -> {
 79	                    new Thread() {
 80	                        @Override
 81	                        public void run() {
 82	                            String title = "About";
 83	
 84	                            StringBuilder aboutString = new StringBuilder();
 85	                            aboutString.append(TermuxUtils.getAppInfoMarkdownString(context, TermuxUtils.AppInfoMode.TERMUX_AND_PLUGIN_PACKAGES));
 86	                            aboutString.append("\n\n").append(AndroidUtils.getDeviceInfoMarkdownString(context, true));
 87	                            aboutString.append("\n\n").append(TermuxUtils.getImportantLinksMarkdownString(context));
 88	
 89	                            String userActionName = UserAction.ABOUT.getName();
 90	
 91	                            ReportInfo reportInfo = new ReportInfo(userActionName,
 92	                                TermuxConstants.TERMUX_APP.TERMUX_SETTINGS_ACTIVITY_NAME, title);
 93	                            reportInfo.setReportString(aboutString.toString());
 94	                            reportInfo.setReportSaveFileLabelAndPath(userActionName,
 95	                                Environment.getExternalStorageDirectory() + "/" +
 96	                                    FileUtils.sanitizeFileName(TermuxConstants.TERMUX_APP_NAME + "-" + userActionName + ".log", true, true));
 97	
 98	                            FragmentActivity activity = getActivity();
 99	                            if (activity == null) return;
100	                            activity.runOnUiThread(() -> ReportActivity.startReportActivity(activity, reportInfo));
101	                        }
102	                    }.start();
103	
104	                    return true;
105	                });
106	            }
107	        }
108	
109	        private void configureDonatePreference(@NonNull Context context) {
110	            Preference donatePreference = findPreference("donate");
111	            if (donatePreference != null) {
112	                String signingCertificateSHA256Digest = PackageUtils.getSigningCertificateSHA256DigestForPackage(context);
113	                if (signingCertificateSHA256Digest != null) {
114	                    // If APK is a Google Playstore release, then do not show the donation link
115	                    // since Termux isn't exempted from the playstore policy donation links restriction
116	                    // Check Fund solicitations: https://pay.google.com/intl/en_in/about/policy/
117	                    String apkRelease = TermuxUtils.getAPKRelease(signingCertificateSHA256Digest);
118	                    if (apkRelease == null || apkRelease.equals(TermuxConstants.APK_RELEASE_GOOGLE_PLAYSTORE_SIGNING_CERTIFICATE_SHA256_DIGEST)) {
119	                        donatePreference.setVisible(false);
120	                        return;
121	                    } else {
122	                        donatePreference.setVisible(true);
123	                    }
124	                }
125	
126	                donatePreference.setOnPreferenceClickListener(preference -> {
127	                    ShareUtils.openUrl(context, TermuxConstants.TERMUX_DONATE_URL);
128	                    return true;
129	                });
130	            }
131	        }
132	    }
133	
134	}

